<script setup lang="ts">
import { computed, watch } from 'vue';
import { type Row, formatTime, postCategories } from '../../../shared/domain';
import { useWorkCenter, workKinds, type WorkMode } from '../../../shared/useWorkCenter';
import { api } from '../platform';
const props = defineProps<{ user: Row | null; mode: WorkMode; target?: Row | null }>();
const emit = defineEmits<{ (e: 'updated'): void; (e: 'navigate', target: Row): void; (e: 'join'): void }>();
const { rows, total, page, pages, filter, kind, filters, loading, busy, error, detailError, message, selected, pending, form, editing, editForm, opening, target, allowed, load, open, clearDetail, choose, edit, submit, markRead, selectFilter, selectKind, turn } = useWorkCenter(() => props.user, () => props.mode, api, () => emit('updated'));
const heading = computed(() => props.mode === 'mine' ? '我的事项' : props.mode === 'manage' ? '管理待办总览' : '业务通知');
const kindIndex = computed(() => Math.max(0, workKinds.findIndex(k => k.id === kind.value)));
async function openItem(row: Row) { await open(row);uni.pageScrollTo({ scrollTop: 0, duration: 0 }); }
watch(() => props.target, value => { if (value) openItem(value); }, { immediate: true });
function value(row: Row) { return row.label.includes('北京时间') ? formatTime(row.value) + ' · 北京时间' : row.value; }
function changeKind(event: any) { selectKind(workKinds[Number(event.detail.value)].id); }
function changeCategory(event: any) { editForm.value.category = postCategories[Number(event.detail.value)]; }
function changeDays(event: any) { editForm.value.validDays = [7,30,90][Number(event.detail.value)]; }
</script>
<template><view class="work-mobile"><view class="title">{{ heading }}</view><view class="intro">{{ mode === 'notices' ? '已读不代表事情办完，打开详情查看当前进度。' : mode === 'manage' ? '按等待时间处理，只展示你有权处理的事项。' : '进度集中看，下一步直接办。' }}</view><button class="outline" :disabled="loading || busy || !allowed" @click="load">刷新列表</button><view v-if="message" class="notice-line">{{ message }}</view>
<view v-if="!allowed" class="empty">登录后查看你的事项与通知<button class="primary" @click="emit('join')">登录账号</button></view>
<template v-else><view v-if="target" class="panel work-detail"><button class="text-button" :disabled="busy" @click="clearDetail">返回列表</button><view v-if="opening" class="meta">正在核对当前状态…</view><view v-if="detailError" class="error">{{ detailError }}<button class="outline" :disabled="busy" @click="openItem(target)">重新加载详情</button></view><template v-if="selected"><view class="card-title">{{ selected.title }}</view><text class="tag">{{ selected.state }}</text><view v-for="(field,index) in selected.fields" :key="index" class="work-field"><view class="meta">{{ field.label }}</view><view class="work-value">{{ value(field) }}</view></view>
<view v-if="!pending && !editing" class="work-actions"><button v-for="action in selected.actions" :key="action.label" class="outline" :disabled="busy" @click="choose(action)">{{ action.label }}</button><button v-if="selected.editForm" class="primary" @click="edit">修改内容／续期</button><button v-if="selected.navigate" class="outline" @click="emit('navigate', selected)">{{ selected.navigate === 'profile' ? '修改会员资料' : selected.navigate === 'forum' ? '查看论坛原内容' : '前往签到' }}</button></view>
<view v-if="pending" class="form-page"><view class="form-title">{{ pending.label }}</view><view class="safe-note">{{ pending.hint || '请核对当前记录后确认操作。' }}</view><view v-if="pending.field" class="field"><text class="field-label">{{ pending.hint }}</text><textarea v-model="form[pending.field]" :maxlength="pending.max" :aria-label="pending.hint" /></view><view class="work-actions"><button class="primary" :disabled="busy" @click="submit">{{ busy ? '处理中…' : '确认操作' }}</button><button class="outline" :disabled="busy" @click="pending = null">返回</button></view></view>
<view v-if="editing" class="form-page"><view class="form-title">修改互助信息</view><view class="safe-note">修改提交审核，通过前保留原公开内容。</view><view class="field"><text class="field-label">标题</text><input v-model="editForm.title" aria-label="互助标题" maxlength="80" /></view><view class="field"><text class="field-label">分类</text><picker :range="postCategories" :value="postCategories.indexOf(editForm.category)" @change="changeCategory"><view class="picker-value">{{ editForm.category }} ▾</view></picker></view><view class="field"><text class="field-label">片区</text><input v-model="editForm.district" aria-label="互助片区" maxlength="50" placeholder="无需详细住址" /></view><view class="field"><text class="field-label">内容</text><textarea v-model="editForm.content" aria-label="互助内容" maxlength="3000" /></view><view class="field"><text class="field-label">联系信息（仅审核会员可见）</text><input v-model="editForm.contact" aria-label="互助联系信息" maxlength="80" /></view><view class="field"><text class="field-label">有效期</text><picker :range="['7天','30天','90天']" :value="[7,30,90].indexOf(editForm.validDays)" @change="changeDays"><view class="picker-value">{{ editForm.validDays }}天 ▾</view></picker></view><view class="work-actions"><button class="primary" :disabled="busy" @click="submit">{{ busy ? '提交中…' : '提交修改审核' }}</button><button class="outline" :disabled="busy" @click="editing = false">取消编辑</button></view></view></template></view>
<template v-else><view class="work-tabs"><button v-for="item in filters" :key="item.id" :class="filter === item.id ? 'primary' : 'outline'" :disabled="busy" @click="selectFilter(item.id)">{{ item.label }}</button></view><picker v-if="mode !== 'notices'" :range="workKinds.map(k => k.label)" :value="kindIndex" @change="changeKind"><view class="picker-value">{{ workKinds[kindIndex].label }} ▾</view></picker><button v-else class="outline" :disabled="busy || loading || !!error || !total" @click="markRead()">将本次查询之前的通知标为已读</button><view v-if="error" class="error">{{ error }}</view><view v-if="loading" class="meta">正在加载…</view><view v-else-if="!error" class="meta">共 {{ total }} 条</view><view v-if="!loading && !error && !rows.length" class="empty">{{ mode === 'notices' ? '暂无符合条件的通知' : '当前筛选下没有事项' }}</view><view v-for="row in rows" :key="row.kind + row.id" class="panel"><text class="tag">{{ mode === 'notices' ? (row.read ? '已读' : '未读') : row.kindLabel }}</text><view class="card-title">{{ row.title || row.message }}</view><view v-if="row.state" class="notice-line">{{ row.state }}</view><view v-if="row.deadline" class="meta">安排：{{ formatTime(row.deadline) }} · 北京时间</view><view class="meta">{{ mode === 'manage' ? '提交于 ' : '更新于 ' }}{{ formatTime(mode === 'manage' ? row.waitingSince : row.updatedAt || row.createdAt) }}</view><view class="work-actions"><button class="primary" :disabled="busy" @click="openItem(row)">查看详情</button><button v-if="mode === 'notices' && !row.read" class="outline" :disabled="busy" @click="markRead(row)">标为已读</button></view></view><view v-if="pages > 1" class="work-pages"><button class="outline" :disabled="page <= 1 || loading || busy" @click="turn(page - 1)">上一页</button><text>{{ page }}／{{ pages }}</text><button class="outline" :disabled="page >= pages || loading || busy" @click="turn(page + 1)">下一页</button></view></template></template></view></template>
<style scoped>.work-mobile{min-width:0;margin:24rpx 0}.work-tabs,.work-actions,.work-pages{display:flex;gap:16rpx;flex-wrap:wrap;margin:24rpx 0;align-items:center}.work-mobile button{min-height:44px;margin:0;white-space:normal;line-height:1.5}.work-tabs button{font-size:26rpx;padding:16rpx 22rpx}.work-field{margin:28rpx 0}.work-value{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;font-size:28rpx;margin-top:6rpx}.work-detail{padding:26rpx}.work-detail .form-page{padding:0;border-top:1px solid #dce4ed;margin-top:30rpx}.work-mobile .card-title{overflow-wrap:anywhere}.work-pages{justify-content:space-between}.work-mobile .picker-value{margin:20rpx 0}.work-mobile .title{font-size:44rpx}</style>
